import { MessageChannelFactory, BaseMessageChannel } from '../message-channels';
import { IGameParentEvents, IErrorPayload, IUserActionPayload, IOperatorMessagePayload, IAuthenticatedPayload, ISessionInfoPayload, IGameThemeUpdatePayload, IGameChildEvents, IGameConfigPayload, IGameConnectionOptions, IGameInPlayPayload, IGameRedirectPayload, IOpenSubGamePayload, IOpenSubGameUrlPayload, IRequestSubGameUrlPayload } from '../types';
import { AuthTimeout } from '../utilis';

export class OperatorProxy implements IGameParentEvents {
    private messageChannel: BaseMessageChannel<IGameParentEvents, IGameChildEvents>;

    constructor(options: IGameConnectionOptions) {
        if (options.type === 'native') {
            this.messageChannel = MessageChannelFactory.create({
                type: options.type,
                platform: options.platform,
                source: 'game',
                handlers: options.operatorHandlers
            });
        } else {
            this.messageChannel = MessageChannelFactory.create({
                type: options.type,
                target: window,
                source: 'game'
            });
        }
    }
    public updateGameInPlay(payload: IGameInPlayPayload): void {
        this.messageChannel.send('updateGameInPlay', payload);
    }

    public async onInit(payload: IGameConfigPayload): Promise<void> {
        this.messageChannel.send('onInit', payload);

        AuthTimeout.start(() => this.onError({
            code: 3,
            message: `Auth Timeout ${AuthTimeout.TIMEOUT}ms`
        }));

        await this.messageChannel.waitForResponse('authenticate', 'operator');
    }

    public onLoaded(): void {
        this.messageChannel.send('onLoaded', void 0);
    }

    public onAuthenticated(payload: IAuthenticatedPayload): void {
        this.messageChannel.send('onAuthenticated', payload);
    }

    public onSessionInfo(payload: ISessionInfoPayload): void {
        this.messageChannel.send('onSessionInfo', payload);
    }

    public onSessionTimeout(): void {
        this.messageChannel.send('onSessionTimeout', void 0);
    }

    public onUserActionRequired(payload: IUserActionPayload): void {
        this.messageChannel.send('onUserActionRequired', payload);
    }

    public onStyleUpdate(payload: IGameThemeUpdatePayload): void {
        this.messageChannel.send('onStyleUpdate', payload);
    }

    public onRequestSubGameUrl(payload: IRequestSubGameUrlPayload): void {
        this.messageChannel.send('onRequestSubGameUrl', payload);
    }

    public openSubGame(payload: IOpenSubGamePayload): void {
        this.messageChannel.send('openSubGame', payload);
    }
    
    public openSubGameUrl(payload: IOpenSubGameUrlPayload): void {
        this.messageChannel.send('openSubGameUrl', payload);
    }

    public onOperatorMessage(payload: IOperatorMessagePayload): void {
        this.messageChannel.send('onOperatorMessage', payload);
    }

    public onGameStart(): void {
        this.messageChannel.send('onGameStart', void 0);
    }

    public onGameEnd(): void {
        this.messageChannel.send('onGameEnd', void 0);
    }

    public onCloseGame(): void {
        this.messageChannel.send('onCloseGame', void 0);
    }

    public onError(payload: IErrorPayload): void {
        this.messageChannel.send('onError', payload);
    }

    public onGameRedirect(payload: IGameRedirectPayload): void {
        this.messageChannel.send('onGameRedirect', payload);
    }

    public onSettingsClosed(): void {
        this.messageChannel.send('onSettingsClosed', void 0);
    }

    public onConnected(): void {
        this.messageChannel.send('onConnected', void 0);
    }
}